export async function gate({ referenceDir, submissionDir }) {
  const fs = await import('node:fs');
  const path = await import('node:path');
  const crypto = await import('node:crypto');
  const { spawn } = await import('node:child_process');

  const nonce = crypto.randomBytes(16).toString('hex');
  const runnerPath = path.join(referenceDir, '_gate_runner_' + nonce + '.mjs');
  const resultPath = path.join(referenceDir, '_gate_result_' + nonce + '.json');
  const submissionPath = path.join(submissionDir, 'answer.mjs');

  const runner = `
import fs from 'node:fs';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';

const resultPath = ${JSON.stringify(resultPath)};
const nonce = ${JSON.stringify(nonce)};
const submissionPath = ${JSON.stringify(submissionPath)};

function writeResult(obj) {
  fs.writeFileSync(resultPath, JSON.stringify({ nonce, ...obj }));
}

try {
  const mod = await import(pathToFileURL(submissionPath).href);
  const dedupeSorted = mod.dedupeSorted;
  if (typeof dedupeSorted !== 'function') {
    writeResult({ ok: false, reason: 'dedupeSorted is not a function', done: 1, n: 0 });
    process.exit(0);
  }
  const tests = [
    ['empty array', () => { assert.deepStrictEqual(dedupeSorted([]), []); }],
    ['single element', () => { assert.deepStrictEqual(dedupeSorted([5]), [5]); }],
    ['no duplicates', () => { assert.deepStrictEqual(dedupeSorted([1, 2, 3]), [1, 2, 3]); }],
    ['all duplicates', () => { assert.deepStrictEqual(dedupeSorted([4, 4, 4, 4]), [4]); }],
    ['duplicates at the start', () => { assert.deepStrictEqual(dedupeSorted([1, 1, 2, 3]), [1, 2, 3]); }],
    ['duplicates at the end', () => { assert.deepStrictEqual(dedupeSorted([1, 2, 3, 3]), [1, 2, 3]); }],
    ['negative numbers with duplicates', () => { assert.deepStrictEqual(dedupeSorted([-3, -3, -1, 0, 0, 2]), [-3, -1, 0, 2]); }],
    ['randomized property check against a reference oracle', () => {
      for (let trial = 0; trial < 20; trial++) {
        const len = 1 + Math.floor(Math.random() * 10);
        const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 5) - 2).sort((a, b) => a - b);
        const expected = [...new Set(arr)];
        assert.deepStrictEqual(dedupeSorted(arr), expected);
      }
    }]
  ];
  const failures = [];
  for (const [name, fn] of tests) {
    try { fn(); }
    catch (e) { failures.push(name + ': ' + (e && e.message ? e.message : String(e))); }
  }
  writeResult({
    ok: failures.length === 0,
    reason: failures.length === 0 ? ('all ' + tests.length + ' tests passed') : failures.join('; '),
    done: 1,
    n: tests.length
  });
} catch (e) {
  try { writeResult({ ok: false, reason: String(e && e.stack ? e.stack : e), done: 1, n: 0 }); } catch {}
}
`;

  fs.writeFileSync(runnerPath, runner, 'utf8');

  const outcome = await new Promise((resolve) => {
    let settled = false;
    const finish = (v) => { if (!settled) { settled = true; resolve(v); } };

    let child;
    try {
      child = spawn(process.execPath, [runnerPath], {
        stdio: ['ignore', 'ignore', 'ignore'],
        env: { PATH: process.env.PATH || '/usr/bin:/bin' }
      });
    } catch (e) {
      finish({ accept: false, reason: 'spawn failed: ' + e.message });
      return;
    }

    const t = setTimeout(() => {
      try { child.kill('SIGKILL'); } catch {}
      finish({ accept: false, reason: 'timeout before suite completion' });
    }, 15000);

    child.on('error', (e) => {
      clearTimeout(t);
      finish({ accept: false, reason: 'child error: ' + e.message });
    });

    child.on('close', () => {
      clearTimeout(t);
      try {
        const parsed = JSON.parse(fs.readFileSync(resultPath, 'utf8'));
        if (parsed.nonce !== nonce || parsed.done !== 1 || parsed.n !== 8) {
          finish({ accept: false, reason: 'suite did not establish completion' });
          return;
        }
        finish({ accept: parsed.ok === true, reason: String(parsed.reason || '') });
      } catch {
        finish({ accept: false, reason: 'suite did not run to completion' });
      }
    });
  });

  try { fs.unlinkSync(runnerPath); } catch {}
  try { fs.unlinkSync(resultPath); } catch {}
  return outcome;
}

